def merge_headers(default: dict[str, str] | None, extra: dict[str, str] | None) -> dict[str, str]:
    """Merge two header dicts.

    * Header names are treated case‑insensitively – later values win regardless of case.
    * All header values are stripped of leading/trailing whitespace.
    * ``default`` or ``extra`` may be ``None`` and are treated as empty dicts.

    Returns a new dict with normalized (lower‑cased) header names.
    """
    default = default or {}
    extra = extra or {}
    merged: dict[str, str] = {}
    for k, v in default.items():
        merged[k.lower()] = v.strip()
    for k, v in extra.items():
        merged[k.lower()] = v.strip()
    return merged
