from mcp.shared._compat import merge_headers

def test_merge_headers_basic():
    default = {"Content-Type": " application/json ", "Accept": "*/*"}
    extra = {"content-type": "text/html", "X-Custom": "  value  "}
    merged = merge_headers(default, extra)
    assert merged == {
        "content-type": "text/html",  # extra overrides default, case‑insensitive
        "accept": "*/*",
        "x-custom": "value",
    }

def test_merge_headers_none_inputs():
    assert merge_headers(None, None) == {}
    assert merge_headers({"A": " B "}, None) == {"a": "B"}
    assert merge_headers(None, {"C": " D "}) == {"c": "D"}
